,onSelected:(_)=>setState(()=>filter='all')),ChoiceChip(label:const Text('عليهم دين'),selected:filter=='debt',onSelected:(_)=>setState(()=>filter='debt')),ChoiceChip(label:const Text('مسدد'),selected:filter=='paid',onSelected:(_)=>setState(()=>filter='paid'))]),...list.map((x)=>Card(child:ListTile(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>CustomerPage(store:s,customer:x))),title:Text(x.name),subtitle:Text('${x.phone}\n${s.risk(x.id)} • دين ${money(s.debts(x.id))} • مسدد ${money(s.paid(x.id))}'),isThreeLine:true,trailing:Text(money(s.balance(x.id)),style:const TextStyle(fontWeight:FontWeight.bold)))))]),floatingActionButton:FloatingActionButton.extended(onPressed:s.locked?()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ActivationPage(store:s))):()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>AddCustomerPage(store:s))),icon:Icon(s.locked?Icons.lock:Icons.person_add),label:Text(s.locked?'التفعيل':'عميل')));}}
