class _AdminPageState extends State<AdminPage>{final device=TextEditingController();String result='';Future<void>generate()async{final x=await widget.store.generateCode(device.text);if(mounted)setState(()=>result=x??'تعذر التوليد — تحقق من Firebase');}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('Adreemk — المالك')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('توليد رمز دائم خاص بعميل واحد'),TextField(controller:device,decoration:const InputDecoration(labelText:'رقم جهاز العميل')),FilledButton(onPressed:generate,child:const Text('توليد الرمز')),if(result.isNotEmpty)Card(child:ListTile(title:const Text('رمز التفعيل'),subtitle:Text(result,style:const TextStyle(fontSize:28,fontWeight:FontWeight.bold)),trailing:IconButton(onPressed:()=>launchUrl(Uri.https('wa.me','/218934951072',{'text':'رمز تفعيل DainPay: $result'}),mode:LaunchMode.externalApplication),icon:const Icon(Icons.send))))]));}}
